/// <summary>
/// The surface of a host that streams output (§12.1a): buffered_output is
/// written as false and exposure_bound is present.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class UnbufferedSurface : Surface
{
    /// <summary>
    /// Points the host emits; always includes agent_startup, input, output and
    /// agent_shutdown (§3.2), and omits the model or tool points only in pairs.
    /// </summary>
    [JsonPropertyName("interception_points")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public InterceptionPoint[]? InterceptionPoints { get; set; }

    [JsonPropertyName("capabilities")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Capability[]? Capabilities { get; set; }

    [JsonPropertyName("profiles")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ProfileSupport? Profiles { get; set; }

    /// <summary>
    /// §12.1a. false must be declared explicitly and requires exposure_bound.
    /// </summary>
    [JsonPropertyName("buffered_output")]
    [JsonRequired]
    public bool BufferedOutput
    {
        get { return false; }
        set { if (value != false) throw new JsonException("Expected buffered_output = false."); }
    }

    /// <summary>
    /// §12.1a. Present iff buffered_output is false.
    /// </summary>
    [JsonPropertyName("exposure_bound")]
    public required string ExposureBound { get; set; }
}

[JsonConverter(typeof(ApprovalResolutionJsonConverter))]
public interface ApprovalResolution;

internal sealed class ApprovalResolutionJsonConverter : DiscriminatedUnionJsonConverter<ApprovalResolution>
{
    public ApprovalResolutionJsonConverter() : base(
        "outcome",
        new Dictionary<(JsonValueKind, string), Type>
        {
            [(JsonValueKind.String, "approve")] = typeof(ApproveResolution),
            [(JsonValueKind.String, "reject")] = typeof(RejectResolution),
            [(JsonValueKind.String, "unresolved")] = typeof(UnresolvedResolution),
        },
        null
    ) {}
}

/// <summary>
/// approve: the resolver lifts the deny with an allow verdict.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class ApproveResolution : ApprovalResolution
{
    /// <summary>
    /// MUST equal the request's context_identity byte for byte (echo rule, §9);
    /// null echoes as null.
    /// </summary>
    [JsonPropertyName("context_identity")]
    public required string? ContextIdentity { get; set; }

    [JsonPropertyName("outcome")]
    [JsonRequired]
    public Outcome Outcome
    {
        get { return Outcome.Approve; }
        set { if (value != Outcome.Approve) throw new JsonException("Expected outcome = approve."); }
    }

    [JsonPropertyName("verdict")]
    public required AllowVerdict Verdict { get; set; }
}

/// <summary>
/// How a consultation ended (§9).
/// </summary>
[JsonConverter(typeof(OutcomeJsonConverter))]
public enum Outcome
{
    Approve,
    Reject,
    Unresolved
}

internal sealed class OutcomeJsonConverter : StringEnumJsonConverter<Outcome>
{
    public OutcomeJsonConverter() : base(
        new Dictionary<Outcome, string>
        {
            [Outcome.Approve] = "approve",
            [Outcome.Reject] = "reject",
            [Outcome.Unresolved] = "unresolved",
        }
    ) {}
}

/// <summary>
/// reject: the resolver keeps a deny.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class RejectResolution : ApprovalResolution
{
    /// <summary>
    /// MUST equal the request's context_identity byte for byte (echo rule, §9);
    /// null echoes as null.
    /// </summary>
    [JsonPropertyName("context_identity")]
    public required string? ContextIdentity { get; set; }

    [JsonPropertyName("outcome")]
    [JsonRequired]
    public Outcome Outcome
    {
        get { return Outcome.Reject; }
        set { if (value != Outcome.Reject) throw new JsonException("Expected outcome = reject."); }
    }

    [JsonPropertyName("verdict")]
    public required DenyVerdict Verdict { get; set; }
}

/// <summary>
/// unresolved: no decision; the deny stands and no verdict is carried.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class UnresolvedResolution : ApprovalResolution
{
    /// <summary>
    /// MUST equal the request's context_identity byte for byte (echo rule, §9);
    /// null echoes as null.
    /// </summary>
    [JsonPropertyName("context_identity")]
    public required string? ContextIdentity { get; set; }

    [JsonPropertyName("outcome")]
    [JsonRequired]
    public Outcome Outcome
    {
        get { return Outcome.Unresolved; }
        set { if (value != Outcome.Unresolved) throw new JsonException("Expected outcome = unresolved."); }
    }
}
